#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    int d = b - a;
    if (c == 0) {
        if (a == b)
            printf("YES");
        else
            printf("NO");
    } else {
        if (d % c == 0 && ((c > 0 && d >= 0) || (c < 0 && d <= 0)))
            printf("YES");
        else
            printf("NO");
    }
    return 0;
}

